"""Invoice totals in yen. Each line is (unit_price, quantity). Consumption tax is 10%."""

TAX_RATE_PERCENT = 10


def line_total(unit_price, quantity):
    return unit_price * quantity


def _pre_tax_subtotal(lines):
    return sum(line_total(p, q) for p, q in lines)


def _with_tax(amount):
    # integer arithmetic; rounds half up once (round() would be banker's rounding on floats)
    return (amount * (100 + TAX_RATE_PERCENT) + 50) // 100


def subtotal(lines):
    # tax-inclusive
    return _with_tax(_pre_tax_subtotal(lines))


def total_with_tax(lines):
    # tax is applied to the pre-tax subtotal and rounded once for the whole invoice
    return _with_tax(_pre_tax_subtotal(lines))
